use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::Array(arr) = input {
        let mut result = String::new();
        for byte in arr {
            if let Value::Number(num) = byte {
                if let Some(int) = num.as_i64() {
                    let hex = format!("{:02x}", int);
                    result.push_str(&hex);
                }
            }
        }
        Value::String(result)
    } else {
        Value::Null
    }
}
